import { Parser, ReplacementRules, popKeys } from './parser';
import { Generators, createPromptInfo, createSampler, createModel, PromptInfo } from '../data';
import { ParserError } from '../exceptions';
import { readJsonObject, take, promptList } from './helpers';

const SAMPLER_PARAMS = ['seed', 'steps', 'cfg', 'scheduler', 'denoise', 'clip_skip'];
const REPLACEMENT_RULES: ReplacementRules = [['cfg', 'cfg_scale']];

/**
 * Parser for images generated by RuinedFooocus
 */
export class RuinedFooocusParser extends Parser {
  public readonly generator = Generators.RUINED_FOOOCUS;

  async parse(parameters: Record<string, any>): Promise<PromptInfo> {
    const source = parameters.parameters ?? parameters.UserComment;
    if (typeof source !== 'string' || !source.includes('RuinedFooocus')) {
      throw new ParserError('no RuinedFooocus parameters found');
    }
    const params = readJsonObject(source);
    if (params.software !== 'RuinedFooocus') {
      throw new ParserError('no RuinedFooocus parameters found');
    }
    delete params.software;

    const samplerName = take(params, 'sampler_name') ?? 'unknown';
    const prompt = take(params, 'Prompt');
    const negativePrompt = take(params, 'Negative');
    const name = take(params, 'base_model_name');
    const hash = take(params, 'base_model_hash');
    const model = name || hash ? createModel({ name: name ?? undefined, hash: hash ?? undefined }) : undefined;

    const samplerParameters = Object.fromEntries(popKeys(SAMPLER_PARAMS, params).filter(([, value]) => value != null));
    const sampler = createSampler(samplerName, this.normalizeParameters(samplerParameters, REPLACEMENT_RULES), {
      model,
      prompts: promptList(prompt),
      negativePrompts: promptList(negativePrompt),
    });

    return createPromptInfo(this.generator, [sampler], params, parameters);
  }
}
